<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import api,{unwrap}from'@/api';import type{PageData}from'@/types';import{Upload,Refresh,Search,Delete}from'@element-plus/icons-vue';import{ElMessage,ElMessageBox}from'element-plus'
const docs=ref<any[]>([]),uploadDialog=ref(false),searchDialog=ref(false),file=ref<File>(),uploading=ref(false),query=ref('幼果膨大期大雨前如何管理水肥'),results=ref<any[]>([]),meta=reactive({name:'',source:'',region:'福建',documentType:'技术资料',phenology:'FRUIT_EXPANSION'})
async function load(){docs.value=unwrap<PageData<any>>(await api.get('/knowledge/documents?pageSize=100')).items}function selectFile(raw:any){file.value=raw.raw}
async function upload(){if(!file.value)return ElMessage.warning('请选择文档');const fd=new FormData();fd.append('file',file.value);Object.entries(meta).forEach(([k,v])=>fd.append(k,v));uploading.value=true;try{await api.post('/knowledge/documents',fd);ElMessage.success('文档已解析并建立索引');uploadDialog.value=false;file.value=undefined;load()}finally{uploading.value=false}}
async function reindex(id:string){await api.post(`/knowledge/documents/${id}/reindex`);ElMessage.success('重新处理完成');load()}async function remove(id:string){await ElMessageBox.confirm('删除文档及其检索片段？','确认删除',{type:'warning'});await api.delete(`/knowledge/documents/${id}`);load()}async function search(){results.value=unwrap<any[]>(await api.post('/knowledge/search-test',{query:query.value,topK:5}));searchDialog.value=true}onMounted(load)
</script><template><div><div class="page-title-row"><div><h2>专业知识库</h2><p>{{docs.length}} 份资料 · 文档解析、向量化与来源追踪</p></div><div class="toolbar"><el-input v-model="query" style="width:280px" placeholder="检索测试" @keyup.enter="search"><template #append><el-button :icon="Search" @click="search"/></template></el-input><el-button type="primary" :icon="Upload" @click="uploadDialog=true">上传资料</el-button></div></div><section class="panel"><el-table :data="docs" stripe><el-table-column prop="name" label="资料名称" min-width="230"><template #default="{row}"><strong>{{row.name}}</strong><div class="doc-source">{{row.source}} · {{row.documentType}}</div></template></el-table-column><el-table-column prop="region" label="适用地区" width="120"/><el-table-column prop="phenology" label="物候期" width="145"/><el-table-column prop="chunkCount" label="片段" width="80"/><el-table-column label="状态" width="105"><template #default="{row}"><el-tag :type="row.status==='SUCCESS'?'success':row.status==='FAILED'?'danger':'warning'" effect="plain">{{row.status}}</el-tag></template></el-table-column><el-table-column prop="updatedAt" label="更新时间" width="185"/><el-table-column label="操作" width="120" fixed="right"><template #default="{row}"><el-button circle :icon="Refresh" title="重新处理" @click="reindex(row.id)"/><el-button circle :icon="Delete" title="删除" @click="remove(row.id)"/></template></el-table-column></el-table></section><el-dialog v-model="uploadDialog" title="上传知识资料" width="min(560px,92vw)"><el-upload drag :auto-upload="false" :limit="1" accept=".pdf,.docx,.txt,.md,.markdown" :on-change="selectFile"><el-icon class="upload-icon"><Upload/></el-icon><div>选择或拖入 PDF、DOCX、TXT、Markdown</div></el-upload><el-form label-position="top" class="meta-form"><el-form-item label="资料名称"><el-input v-model="meta.name" placeholder="留空使用文件名"/></el-form-item><el-form-item label="来源单位"><el-input v-model="meta.source"/></el-form-item><div class="form-pair"><el-form-item label="适用地区"><el-input v-model="meta.region"/></el-form-item><el-form-item label="资料类型"><el-input v-model="meta.documentType"/></el-form-item></div></el-form><template #footer><el-button @click="uploadDialog=false">取消</el-button><el-button type="primary" :loading="uploading" @click="upload">上传并索引</el-button></template></el-dialog><el-dialog v-model="searchDialog" title="向量检索结果" width="min(720px,94vw)"><div v-if="!results.length" class="muted">未找到可靠知识来源</div><div v-for="r in results" :key="r.documentId+'-'+r.chunkNo" class="search-hit"><header><strong>{{r.documentName}} · 片段 {{r.chunkNo}}</strong><span>{{r.score}}</span></header><p>{{r.content}}</p><small>{{r.source}}</small></div></el-dialog></div></template><style scoped>.doc-source{font-size:11px;color:var(--muted);margin-top:4px}.upload-icon{font-size:30px;color:var(--green);margin-bottom:8px}.meta-form{margin-top:18px}.form-pair{display:grid;grid-template-columns:1fr 1fr;gap:12px}.search-hit{padding:14px;border:1px solid var(--line);border-radius:5px;margin-bottom:10px}.search-hit header{display:flex;justify-content:space-between;font-size:12px}.search-hit header span{color:var(--green);font-weight:700}.search-hit p{font-size:12px;line-height:1.7;color:#4f5b54}.search-hit small{color:var(--muted)}@media(max-width:600px){.form-pair{grid-template-columns:1fr}.toolbar .el-input{width:100%!important}}</style>

